import{_ as e,o as a,c as s,a5 as i}from"./chunks/framework.CQwNn0Y-.js";const k=JSON.parse('{"title":"安装","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md","lastUpdated":1792245757000}'),d={name:"guide/install.md"};function l(n,t,r,h,o,c){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h1><p>ZenFile 提供安装版与便携版两种分发形态，均位于 <a href="https://github.com/LOGYTEA/ZenFile/releases" target="_blank" rel="noreferrer">Releases</a> 的 Assets 目录。</p><h2 id="安装版" tabindex="-1">安装版 <a class="header-anchor" href="#安装版" aria-label="Permalink to “安装版”">​</a></h2><p><code>ZenFile-setup-&lt;版本号&gt;.exe</code> 是单文件自解压安装包。双击执行后默认安装到</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>%LOCALAPPDATA%\\Programs\\ZenFile</span></span></code></pre></div><p>并创建桌面与开始菜单快捷方式。</p><p>需要装到别的位置，可以直接把路径作为参数传给它：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ZenFile-setup-0.3-Beta-Weekly26-10-17.exe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;D:\\Applications\\ZenFile&quot;</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">卸载</p><p>安装版不做注册表登记，卸载即删除安装目录。配置写在 <code>%APPDATA%\\ZenFile\\</code>， 需要彻底清理时一并删除该目录。</p></div><h2 id="便携版" tabindex="-1">便携版 <a class="header-anchor" href="#便携版" aria-label="Permalink to “便携版”">​</a></h2><p><code>ZenFile-portable-&lt;版本号&gt;.zip</code> 解压即用，无需安装。解压后的目录结构：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ZenFile-portable-0.3-Beta/</span></span>
<span class="line"><span>├── ZenFile.exe</span></span>
<span class="line"><span>├── plugins/           ← 插件放这里（不是 %APPDATA%）</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><p>配置写入 <code>%APPDATA%\\ZenFile\\</code>，插件目录在可执行文件<strong>同级</strong>。 因此解压目录可以整体复制或移动，绿色便携运行。</p><div class="warning custom-block"><p class="custom-block-title">插件目录的位置</p><p>插件目录必须和 <code>ZenFile.exe</code> 放在一起，不是 exe 的工作目录。 放错位置「设置 - 插件」面板会显示「没有找到插件」。</p></div><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to “系统要求”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>操作系统</td><td>Windows 10 / 11 x64</td></tr><tr><td>运行时</td><td><strong>无需任何运行时</strong></td></tr><tr><td>内存</td><td>空闲常驻 29.5 MB</td></tr></tbody></table><p>不依赖 WebView2、Node.js、.NET、Visual C++ 运行库。</p><h2 id="命令行参数" tabindex="-1">命令行参数 <a class="header-anchor" href="#命令行参数" aria-label="Permalink to “命令行参数”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>--selftest</code></td><td>执行无界面自检，全部通过时返回 0</td></tr><tr><td><code>--version</code></td><td>输出版本号与协议版本</td></tr><tr><td><code>--tray</code></td><td>以托盘模式启动</td></tr><tr><td><code>--new-process</code></td><td>强制创建新进程，不占用单实例互斥量</td></tr><tr><td><code>--plugin &lt;id&gt;</code></td><td>以插件进程身份启动，由宿主调用</td></tr><tr><td><code>--anim-trace &lt;ms&gt;</code></td><td>帧链路埋点记录到 <code>%TEMP%</code> 下的 CSV</td></tr></tbody></table><h2 id="从源码构建" tabindex="-1">从源码构建 <a class="header-anchor" href="#从源码构建" aria-label="Permalink to “从源码构建”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/LOGYTEA/ZenFile.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ZenFile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 产出 target/release/ZenFile.exe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zenfile-core</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 内核单元测试</span></span></code></pre></div><p>需要 Rust 1.85 及以上（msvc 目标）。构建出的可执行文件同样是单文件、无外部依赖。</p><h2 id="与资源管理器互通" tabindex="-1">与资源管理器互通 <a class="header-anchor" href="#与资源管理器互通" aria-label="Permalink to “与资源管理器互通”">​</a></h2><p>ZenFile 使用系统标准的 <code>CF_HDROP</code> + <code>Preferred DropEffect</code> 剪贴板格式， 与 Windows 资源管理器<strong>双向互通</strong>：</p><ul><li>在 ZenFile 里复制的文件，到资源管理器里可以直接 <code>Ctrl+V</code> 粘贴</li><li>在资源管理器里复制的文件，到 ZenFile 里 <code>Ctrl+V</code> 同样有效</li><li>支持跨 ZenFile 实例复制粘贴</li></ul><h2 id="默认快捷键" tabindex="-1">默认快捷键 <a class="header-anchor" href="#默认快捷键" aria-label="Permalink to “默认快捷键”">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>快捷键</th><th>功能</th><th>快捷键</th></tr></thead><tbody><tr><td>显示/隐藏窗口</td><td><code>Ctrl+Alt+F</code></td><td>新建标签</td><td><code>Ctrl+T</code></td></tr><tr><td>后退 / 前进</td><td><code>Alt+←</code> / <code>Alt+→</code> / <code>Alt+↓</code></td><td>上一级目录</td><td><code>Alt+↑</code></td></tr><tr><td>复制 / 剪切 / 粘贴</td><td><code>Ctrl+C</code> / <code>Ctrl+X</code> / <code>Ctrl+V</code></td><td>全选</td><td><code>Ctrl+A</code></td></tr><tr><td>重命名</td><td><code>F2</code></td><td>删除</td><td><code>Delete</code></td></tr><tr><td>永久删除</td><td><code>Shift+Delete</code></td><td>刷新</td><td><code>F5</code></td></tr><tr><td>新建文件夹</td><td><code>Ctrl+Shift+N</code></td><td>切换视图</td><td><code>Ctrl+Shift+V</code></td></tr><tr><td>定位地址栏</td><td><code>Ctrl+L</code></td><td>定位搜索框</td><td><code>Ctrl+F</code></td></tr></tbody></table><p>全部 18 条均可在「设置 → 快捷键」中修改。</p><h2 id="已知问题" tabindex="-1">已知问题 <a class="header-anchor" href="#已知问题" aria-label="Permalink to “已知问题”">​</a></h2><ul><li>插件的 <code>call</code> / <code>result</code> 能力调用链路尚未实现（插件可被发现和启动，但调不到能力）</li><li>取消传输操作会残留不完整的目标文件</li></ul>`,30)])])}const g=e(d,[["render",l]]);export{k as __pageData,g as default};
